#include <stdio.h>

/* teste do desafio o-copiador-seguro — counter_protocol (03-tdd 3.9.3).
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo o que o aluno
   digitaria, o freopen troca o stdin por esse arquivo, e a captura do stdout
   acontece dentro do proprio cenario (freopen + fflush, sem fclose no stdout).
   O cenario 1 usa uma palavra de dez letras: a segunda linha so pode sair
   certa se o limite da copia tiver cortado o texto em sete letras — imprimir
   a palavra lida duas vezes reprova. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oCopiadorSeguro(void);

SM_TEST(a_etiqueta_cortada) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "computador\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    oCopiadorSeguro();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a palavra digitada", linha, "computador\n",
              "a palavra lida sai inteira: a caixa dela tem cinquenta gavetas");
    fgets(linha, 80, f);
    checa_str("a etiqueta de oito gavetas", linha, "computa\n",
              "sete letras entraram na etiqueta e a oitava gaveta ficou para a placa");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(a_etiqueta_que_cabe) {
    FILE *digitado = fopen("sm_entrada_2.tmp", "w");
    fprintf(digitado, "ana\n");
    fclose(digitado);
    freopen("sm_entrada_2.tmp", "r", stdin);

