#include <stdio.h>
#include <string.h>

void oCopiadorSeguro(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    char etiqueta[8] = "";
    strncpy(etiqueta, palavra, sizeof etiqueta);
    etiqueta[sizeof etiqueta - 1] = '\0';
    printf("%s\n", palavra);
    printf("%s\n", etiqueta);
}
